// === Tab: mySketch ===
let vertSrc = `#version 300 es
	uniform mat4 uModelViewMatrix;
	uniform mat4 uProjectionMatrix;

	in vec3 aPosition;
	in vec2 aTexCoord;
	out vec2 fragCoord;

	void main() {
		// transferring texcoords for the frag shader
		fragCoord = aTexCoord;

		// copy position with a fourth coordinate for projection (1.0 is normal)
		vec4 positionVec4 = vec4(aPosition, 1.0);

		// project to 3D space
		gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
	}
`

// Create a string with the fragment shader program.
// The fragment shader is called for each pixel.
let fragSrc = `#version 300 es
precision highp float;
precision lowp sampler2D;

// in degrees
uniform vec3 deviceOrientation;
// rgb, 0..1
uniform vec3 searchColor;

// shadertoy compatibility
uniform sampler2D iChannel0;
uniform sampler2D iChannel1;
uniform vec2 iResolution;
uniform float iTime;
out vec4 fragColor;
in vec2 fragCoord;

float hueToSine(float hue) {
    const float PI = 3.14159265359;
    return sin(hue * PI);
}

// ret: 0..1 meaning 0 is a total match
float hueDist(vec3 hsv1, vec3 hsv2) {
    return min(abs(hsv1.x - hsv2.x), abs(hsv2.x - hsv1.x + 1.0));
}

// ret: 0..1 meaning 0 is a total match
float valDist(vec3 hsv1, vec3 hsv2) {
    return abs(hsv1.z - hsv2.z);
}

// ret: 0..1 meaning 0 is a total match
float colDist(vec3 hsv1, vec3 hsv2) {
    return 1.-(1.-hueDist(hsv1, hsv2))*(1.-valDist(hsv1, hsv2));
}

// All components are in the range [0…1], including hue.
vec3 rgb2hsv(vec3 c)
{
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

// col: rgb color
// ret: 0..1 1 means high
float mask(vec3 col) {

    vec3 searchColHsv = rgb2hsv(searchColor);
    vec3 texColHsv = rgb2hsv(col);
    float colorDistance = colDist(searchColHsv, texColHsv);
    float minDist = 0.025;
    float maxDist = 0.15;
    return 1.-smoothstep(0., 1., (clamp(colorDistance, minDist, maxDist) - minDist) / (maxDist-minDist));
}

vec4 bump(vec2 tex_coord) {
    // size.x negative means embossed
    const vec2 size = vec2(-1.0,0.0);
    const ivec3 off = ivec3(-1,0,1);

    vec4 wave = texture(iChannel0, tex_coord);
    float s11 = mask(wave.xyz);
    float s01 = mask(textureOffset(iChannel0, tex_coord, off.xy).xyz);
    float s21 = mask(textureOffset(iChannel0, tex_coord, off.zy).xyz);
    float s10 = mask(textureOffset(iChannel0, tex_coord, off.yx).xyz);
    float s12 = mask(textureOffset(iChannel0, tex_coord, off.yz).xyz);
    vec3 va = normalize(vec3(size.xy,s21-s01));
    vec3 vb = normalize(vec3(size.yx,s12-s10));
    return vec4( cross(va,vb), s11 );
}

// cannot be named mainImage, because then the main() method won't be found
void mianImage( out vec4 vFragColor, in vec2 vFragCoord )
{
    // Normalize pixel coordinates (from 0 to 1)
    vec2 uv = vFragCoord.xy;

    // find mask based on color and create normal map
    float lod = 3.0;
    vec3 colLod = texture(iChannel0, uv, lod).xyz;
    float mask = mask(colLod);
    vec4 bump = bump(uv);
    vec3 normal = bump.xyz;
    vec3 pointLight = vec3(cos(radians(deviceOrientation.y)), sin(radians(deviceOrientation.z)), .5);
    float minDistance = distance(vec3(.5, .5, pointLight.z), vec3(.5, .5, .0));
    float maxDistance = distance(vec3(.0, .0, pointLight.z), vec3(1.0, 1.0, .0));
		float lightDistance = minDistance / maxDistance;
    vec3 lightRay = pointLight - vec3(uv.xy, 0.0);
    float diffuseFactor = 1.-clamp(dot(normalize(normal), normalize(lightRay)), 0.3, 1.0) / pow(lightDistance, 0.250);

		// translate reflection in the opposite direction to the beta and gamma angles from the device
		vec2 uvReflection = vec2(abs(sin(uv.x + radians(deviceOrientation.z)/2.0)), abs(sin(uv.y + radians(deviceOrientation.y)/4.0)));
		vec3 bg = texture(iChannel0, uv).xyz;
		vec3 env = texture(iChannel1, uvReflection, 3.0).xyz;
		// apply search color over env reflection
		vec3 reflection = mix(searchColor, env, 0.5);
    vec3 col = mix(bg, reflection, pow(mask, 2.50));
    col = col * (1.-diffuseFactor);
    //col = texture(iChannel0, vFragCoord).xyz;

    // Output to screen
    vFragColor = vec4(col,1.0);
}

void main()
{
    mianImage(fragColor, fragCoord.xy);
		//fragColor = vec4(fragCoord.xy,1.0,1.0);
}
`;

// this variable will hold our shader object
let theShader;

// this variable will hold our createGraphics layer
let shaderTexture;

let img;
let envImg;

// Define variables that would hold the 
// x, y and z values of orientation 
let alpha = 0; 
let beta = 0; 
let gamma = 0;

let isMobileDevice = false;

function setup() {
  createCanvas(512, 512, WEBGL2);
	img = loadImage("https://openprocessing.org/sketch/2489590/files/the-lovers2.jpg");
	envImage = loadImage("https://openprocessing.org/sketch/2489590/files/env2.jpg");
	theShader = createShader(vertSrc, fragSrc);
  if (window.DeviceOrientationEvent) {
    // Add event listener to the function when 
    // the device orientation changes 
		console.log("Start listening...");
		// works with Chrome on Android
    window.addEventListener("deviceorientation",  
      onOrientationChange, true); 
  }

	/* Storing user's device details in a variable*/
  let details = navigator.userAgent;
	console.log("details", details); 

  /* Creating a regular expression 
  containing some mobile devices keywords 
  to search it in details string*/
  let regexp = /android|iphone|kindle|ipad/i;

  /* Using test() method to search regexp in details
  it returns boolean value*/
  isMobileDevice = regexp.test(details);

	console.log("isMobileDevice", isMobileDevice);
} 

function draw() { 
  background(0); 

	// simulate changing device orientation
	if (!isMobileDevice) {
		fakeOrientationChange();
	}

	// send uniform values to the shader
  theShader.setUniform('deviceOrientation', [alpha, beta, gamma]);
	// the color that is dynamically replaced by the metallic shader
  theShader.setUniform('searchColor', [0.941, 0.745, 0.153]);
	// the normal image, in this example the tarot card image
	theShader.setUniform('iChannel0', img);
	// environment image is used for the metallic reflection
	theShader.setUniform('iChannel1', envImage);
	theShader.setUniform('iResolution', [width, height]);
	theShader.setUniform('iTime', millis() / 1000);
	filter(theShader);
} 

function fakeOrientationChange() {
	let f = frameCount/ 50.0;
	let a = sin(f/PI);
	let b = sin(f/HALF_PI);
	let c = sin(f/QUARTER_PI);
	onOrientationChange({
		"alpha": 180+180*a,
		"beta": 180*b,
		"gamma": 90*c
	})
}

// Assign the x, y, z variables to 
// the event details 
function onOrientationChange(e) {
	// from screen up
	// 90° corresponds with pointing west
	// 180° with south
	// 270° with east
	// range: 0 - 360
  alpha = e.alpha;

	// The beta angle is 0° when the device's top and bottom are the same distance from the Earth's surface;
	// it increases toward 180° as the device is tipped forward toward the user, and it decreases toward -180°
	// as the device is tipped backward away from the user.
	// range: -180 to 180
  beta = e.beta;

	// The gamma angle is 0° when the device's left and right sides are the same distance from the surface
	// of the Earth, and increases toward 90° as the device is tipped toward the right, and toward -90° as
	// the device is tipped toward the left.
	// range: -90 - 90
	gamma = e.gamma;
  //console.log("onOrientationChange", e); 
}

